// 测试金字塔比例校验：单元:集成:E2E 大致应为 70:20:10
function pyramidReport(counts) {
  const total = counts.unit + counts.integration + counts.e2e;
  const ratio = {
    unit: Math.round((counts.unit / total) * 100),
    integration: Math.round((counts.integration / total) * 100),
    e2e: Math.round((counts.e2e / total) * 100),
  };
  const healthy = ratio.unit > ratio.integration && ratio.integration > ratio.e2e;
  return { ratio, healthy };
}

console.log(JSON.stringify(pyramidReport({ unit: 70, integration: 20, e2e: 10 })));
console.log(JSON.stringify(pyramidReport({ unit: 20, integration: 20, e2e: 60 })));
